head.script:
(function () {
  var XHTML_NS = "http://www.w3.org/1999/xhtml";
  var foreignObject = document.querySelector("foreignObject");
  if (!foreignObject) return;
  var root = foreignObject.firstElementChild;
  if (!root) return;
  var origCE = document.createElement.bind(document);
  var origCENS = document.createElementNS.bind(document);

  try {
    Object.defineProperty(document, "head", {
      get: function () { return root.querySelector("head"); },
      configurable: true
    });
    Object.defineProperty(document, "body", {
      get: function () { return root.querySelector("body"); },
      configurable: true
    });
    Object.defineProperty(document, "documentElement", {
      get: function () { return root; },
      configurable: true
    });
  } catch (_) {}

  document.createElement = function (tag, options) {
    if (typeof tag === "string") {
      try { return origCENS(XHTML_NS, tag, options); }
      catch (_) { return origCENS(XHTML_NS, tag); }
    }
    return origCE(tag, options);
  };

  document.createElementNS = function (ns, tag, options) {
    if (ns == null || ns === XHTML_NS) {
      try { return origCENS(XHTML_NS, tag, options); }
      catch (_) { return origCENS(XHTML_NS, tag); }
    }
    try { return origCENS(ns, tag, options); }
    catch (_) { return origCENS(ns, tag); }
  };

  try {
    Object.defineProperty(document, "getElementById", {
      value: function (id) {
        var safe = String(id).replace(/["\\]/g, "\\$&");
        return root.querySelector('[id="' + safe + '"]');
      },
      configurable: true,
      writable: true
    });
  } catch (_) {}

  try {
    document.querySelector = function (selector) {
      try { return root.querySelector(selector) || origQS(selector); }
      catch (_) { return origQS(selector); }
    };
    var origQS = document.querySelector.bind(document);
  } catch (_) {}
})();

body.script:
// Synnical OS Desktop Controller
(function() {
  const days = ['SUNDAY','MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY'];
  const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const dayHeaders = ['M','T','W','T','F','S','S'];

  // Dock icons data
  const dockApps = [
    {
      name: 'Browser',
      icon: '<defs><linearGradient id="browserBg" x1="10" y1="8" x2="56" y2="58" gradientUnits="userSpaceOnUse"><stop stop-color="#38bdf8"/><stop offset="1" stop-color="#2563eb"/></linearGradient></defs><rect x="5" y="5" width="24" height="24" rx="7" fill="url(#browserBg)"/><rect x="6" y="6" width="22" height="22" rx="6" fill="none" stroke="rgba(255,255,255,.42)" stroke-width="1.5"/><circle cx="17" cy="17" r="8.8" fill="none" stroke="white" stroke-width="1.8"/><path d="M8.2 17h17.6M17 8.2c3 3.3 4.5 6.3 4.5 8.8s-1.5 5.5-4.5 8.8M17 8.2c-3 3.3-4.5 6.3-4.5 8.8s1.5 5.5 4.5 8.8" fill="none" stroke="white" stroke-width="1.4" stroke-linecap="round"/>'
    },
    {
      name: 'Games',
      icon: '<defs><linearGradient id="gamesBg" x1="10" y1="8" x2="56" y2="58" gradientUnits="userSpaceOnUse"><stop stop-color="#a855f7"/><stop offset="1" stop-color="#db2777"/></linearGradient></defs><rect x="5" y="5" width="24" height="24" rx="7" fill="url(#gamesBg)"/><rect x="6" y="6" width="22" height="22" rx="6" fill="none" stroke="rgba(255,255,255,.42)" stroke-width="1.5"/><path d="M9 18h16c2.8 0 5 2 5 4.5 0 1.9-1.3 3.4-3 3.4-1.2 0-2-.5-3-2.2h-9c-1 1.7-1.8 2.2-3 2.2-1.7 0-3-1.5-3-3.4C9 20 11.2 18 14 18Z" fill="rgba(0,0,0,.24)" stroke="white" stroke-width="1.7" stroke-linejoin="round"/><path d="M12 21v3M10.5 22.5h3M22.5 22h.1M25.5 24h.1" stroke="white" stroke-width="1.7" stroke-linecap="round"/>'
    },
    {
      name: 'Chat',
      icon: '<defs><linearGradient id="chatBg" x1="10" y1="8" x2="56" y2="58" gradientUnits="userSpaceOnUse"><stop stop-color="#22c55e"/><stop offset="1" stop-color="#0f766e"/></linearGradient></defs><rect x="5" y="5" width="24" height="24" rx="7" fill="url(#chatBg)"/><rect x="6" y="6" width="22" height="22" rx="6" fill="none" stroke="rgba(255,255,255,.42)" stroke-width="1.5"/><path d="M9 11h16v11H15l-4.5 3v-3H9z" fill="rgba(0,0,0,.22)" stroke="white" stroke-width="1.8" stroke-linejoin="round"/><path d="M13 16h8M13 19h5" stroke="white" stroke-width="1.8" stroke-linecap="round"/>'
    },
    {
      name: 'SynnFlix',
      icon: '<defs><linearGradient id="flixBg" x1="10" y1="8" x2="56" y2="58" gradientUnits="userSpaceOnUse"><stop stop-color="#ef4444"/><stop offset="1" stop-color="#7f1d1d"/></linearGradient></defs><rect x="5" y="5" width="24" height="24" rx="7" fill="url(#flixBg)"/><rect x="6" y="6" width="22" height="22" rx="6" fill="none" stroke="rgba(255,255,255,.42)" stroke-width="1.5"/><path d="M9 11h16v13H9z" fill="rgba(0,0,0,.3)" stroke="white" stroke-width="1.6" stroke-linejoin="round"/><path d="M9 11l3-3h16l-3 3M13 8l-3 3M21 8l-3 3" fill="none" stroke="white" stroke-width="1.6" stroke-linecap="round"/><path d="M15 15v5l4-2.5z" fill="white"/>'
    },
    {
      name: 'Music',
      icon: '<defs><linearGradient id="musicBg" x1="10" y1="8" x2="56" y2="58" gradientUnits="userSpaceOnUse"><stop stop-color="#f97316"/><stop offset="1" stop-color="#be123c"/></linearGradient></defs><rect x="5" y="5" width="24" height="24" rx="7" fill="url(#musicBg)"/><rect x="6" y="6" width="22" height="22" rx="6" fill="none" stroke="rgba(255,255,255,.42)" stroke-width="1.5"/><path d="M21 9v13.5a4.8 4.8 0 1 1-3-4.5V14l10-2.8V20a4.8 4.8 0 1 1-3-4.5V11z" fill="white" opacity=".96"/>'
    },
    {
      name: 'AI Assistant',
      icon: '<defs><linearGradient id="aiBg" x1="10" y1="8" x2="56" y2="58" gradientUnits="userSpaceOnUse"><stop stop-color="#06b6d4"/><stop offset="1" stop-color="#7c3aed"/></linearGradient></defs><rect x="5" y="5" width="24" height="24" rx="7" fill="url(#aiBg)"/><rect x="6" y="6" width="22" height="22" rx="6" fill="none" stroke="rgba(255,255,255,.42)" stroke-width="1.5"/><rect x="10" y="12" width="14" height="12" rx="4" fill="rgba(0,0,0,.22)" stroke="white" stroke-width="1.7"/><path d="M13 10v2M21 10v2M13.8 18h.1M20.2 18h.1M15.5 22h3" stroke="white" stroke-width="1.7" stroke-linecap="round"/>'
    },
    {
      name: 'YouTube',
      icon: '<rect x="5" y="5" width="24" height="24" rx="7" fill="#ff0000"/><rect x="6" y="6" width="22" height="22" rx="6" fill="none" stroke="rgba(255,255,255,.42)" stroke-width="1.5"/><path d="M14 11.5l8 5.5-8 5.5z" fill="white"/>'
    },
    {
      name: 'GeForce NOW',
      icon: '<rect x="5" y="5" width="24" height="24" rx="7" fill="#76b900"/><rect x="6" y="6" width="22" height="22" rx="6" fill="none" stroke="rgba(255,255,255,.42)" stroke-width="1.5"/><path d="M11 16.2a5.5 5.5 0 0 1 11 0c0 3.6-3 5.8-5.5 7.8-2.5-2-5.5-4.2-5.5-7.8Z" fill="white" opacity=".95"/><path d="M13.5 16.3a3.5 3.5 0 0 1 7 0c0 2.1-1.8 3.3-3.5 4.7-1.7-1.4-3.5-2.6-3.5-4.7Z" fill="#76b900"/>'
    },
    {
      name: 'Temp Mail',
      icon: '<defs><linearGradient id="mailBg" x1="10" y1="8" x2="56" y2="58" gradientUnits="userSpaceOnUse"><stop stop-color="#facc15"/><stop offset="1" stop-color="#f97316"/></linearGradient></defs><rect x="5" y="5" width="24" height="24" rx="7" fill="url(#mailBg)"/><rect x="6" y="6" width="22" height="22" rx="6" fill="none" stroke="rgba(255,255,255,.42)" stroke-width="1.5"/><rect x="10" y="12" width="14" height="10" rx="2" fill="rgba(0,0,0,.18)" stroke="white" stroke-width="1.6"/><path d="m10.5 12.5 6.5 5.5 6.5-5.5" fill="none" stroke="white" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>'
    },
  ];

  // Update clock
  function updateClock() {
    const now = new Date();

    document.getElementById('day-name').textContent = days[now.getDay()];
    document.getElementById('time-main').textContent = 
      String(now.getHours()).padStart(2,'0') + ':' + String(now.getMinutes()).padStart(2,'0');
    document.getElementById('time-sec').textContent = String(now.getSeconds()).padStart(2,'0');
    document.getElementById('full-date').textContent = 
      days[now.getDay()] + ', ' + months[now.getMonth()] + ' ' + now.getDate() + ', ' + now.getFullYear();

    document.getElementById('w-date-day').textContent = now.getDate();
    document.getElementById('w-date-month').textContent = months[now.getMonth()];
    document.getElementById('w-date-year').textContent = now.getFullYear();
    document.getElementById('notes-time').textContent = new Date().toLocaleString();

    document.getElementById('cal-header').textContent = 
      months[now.getMonth()].slice(0,3).toUpperCase() + ' • ' + now.getFullYear();

    buildCalendar(now);
  }

  // Build calendar
  function buildCalendar(date) {
    const grid = document.getElementById('cal-grid');
    if (!grid) return;

    const firstDay = new Date(date.getFullYear(), date.getMonth(), 1).getDay();
    const daysInMonth = new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
    const today = date.getDate();

    let html = dayHeaders.map(d => `<span class="cal-day-header">${d}</span>`).join('');

    const startOffset = firstDay === 0 ? 6 : firstDay - 1;
    for (let i = 0; i < startOffset; i++) html += '<span></span>';
    for (let i = 1; i <= daysInMonth; i++) {
      html += `<span class="cal-day${i === today ? ' today' : ''}">${i}</span>`;
    }

    grid.innerHTML = html;
  }

  // Build dock
  function buildDock() {
    const dock = document.getElementById('dock');
    if (!dock) return;

    let html = '';
    dockApps.forEach(app => {
      html += `<button class="dock-item" title="${app.name}">
        <svg viewBox="0 0 34 34">${app.icon}</svg>
      </button>`;
    });

    // Separator + Trash
    html += `<div class="dock-separator"></div>`;
    html += `<button class="dock-item" title="Trash">
      <svg viewBox="0 0 34 34"><path d="M7 10h20M19 10v18a2 2 0 01-2 2H13a2 2 0 01-2-2V10m3 0V8a2 2 0 012-2h4a2 2 0 012 2v2" stroke="white" stroke-width="1.5" fill="none"/></svg>
    </button>`;

    dock.innerHTML = html;
  }

  // Init
  updateClock();
  buildDock();
  setInterval(updateClock, 1000);

  console.log('%c✨ Synnical OS Desktop Loaded', 'color: #ec4899; font-size: 14px; font-weight: bold;');
})();
